const escapeHtml = (v) => String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const stripForMeasure = (v) => String(v).replace(/<\/?[a-zA-Z][^>]*>/g,'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"');
const visibleLen = (v) => [...stripForMeasure(v)].length;
const text = $input.first().json.text || '';
if (visibleLen(text) < 300) throw new Error('Content too short (< 300 chars).');
if (visibleLen(text) > 3900) throw new Error('Content too long (> 3900 chars).');
const today = new Intl.DateTimeFormat('my-MM', {timeZone:'Asia/Yangon',year:'numeric',month:'long',day:'numeric'}).format(new Date());
const formatted = ['📰 <b>Update — ' + escapeHtml(today) + '</b>','',escapeHtml(text),'','— <i>Sent by n8n</i>'].join('\n');
return [{ json: { text: formatted } }];
